using Mono.Cecil;

public static class InteriorPresentationChecks
{
    public static (int Checks,int Failures) Run(IReadOnlyDictionary<string,TypeDefinition> native,AssemblyDefinition mod,string managedDirectory)
    {
        int checks=0,failures=0;
        void Check(string name,bool good){checks++;if(!good)failures++;Console.WriteLine((good?"PASS ":"FAIL ")+"replay interior "+name);}
        bool Fields(string type,params (string Name,string Type)[] fields)=>native.TryGetValue(type,out var definition)&&fields.All(expected=>definition.Fields.Any(field=>field.Name==expected.Name&&!field.IsStatic&&field.FieldType.FullName==expected.Type));
        var compiled=AllTypes(mod.MainModule.Types).ToDictionary(type=>type.FullName);
        MethodDefinition? Body(string type,string name)=>compiled.TryGetValue(type,out var definition)?definition.Methods.FirstOrDefault(method=>method.Name==name&&method.HasBody):null;
        bool Calls(MethodDefinition? body,string type,string name)=>body?.Body.Instructions.Any(instruction=>instruction.Operand is MethodReference method&&method.DeclaringType.GetElementType().FullName==type&&method.Name==name)==true;
        bool WritesField(MethodDefinition? body,string type,string name)=>body?.Body.Instructions.Any(instruction=>instruction.OpCode.Code==Mono.Cecil.Cil.Code.Stsfld&&instruction.Operand is FieldReference field&&field.DeclaringType.FullName==type&&field.Name==name)==true;
        const string runtime="ReplayMod.Core.ReplayInteriorPresentation";
        var bodies=compiled.Values.Where(type=>type.FullName==runtime||type.FullName.StartsWith(runtime+"/",StringComparison.Ordinal)).SelectMany(type=>type.Methods.Where(method=>method.HasBody)).ToArray();
        bool AnyCall(string type,string name)=>bodies.Any(body=>Calls(body,type,name));
        bool AnyField(string type,string name)=>bodies.Any(body=>body.Body.Instructions.Any(instruction=>instruction.Operand is FieldReference field&&field.DeclaringType.FullName==type&&field.Name==name));
        Check("native detailed cockpit and existing seated-pilot asset references",Fields("Aircraft",("cockpitRenderers","UnityEngine.Renderer[]"),("pilots","Pilot[]"),("cockpit","UnitPart"))&&Fields("Pilot",("skinnedMeshRenderer","UnityEngine.SkinnedMeshRenderer"),("aircraft","Aircraft"),("dead","System.Boolean"),("ejected","System.Boolean")));
        Check("native cockpit overlay and main camera references",Fields("CameraStateManager",("cockpitCamRender","UnityEngine.Camera"),("mainCamera","UnityEngine.Camera"),("cockpitState","CameraCockpitState")));
        Check("native built-in and scriptable render-pipeline callback APIs",native.TryGetValue("UnityEngine.Camera",out var camera)&&camera.Fields.Any(field=>field.Name=="onPreCull"&&field.IsStatic&&field.FieldType.FullName=="UnityEngine.Camera/CameraCallback")&&native.TryGetValue("UnityEngine.Rendering.RenderPipelineManager",out var pipeline)&&new[]{"add_beginCameraRendering","remove_beginCameraRendering"}.All(name=>pipeline.Methods.Any(method=>method.Name==name&&method.IsStatic&&method.ReturnType.FullName=="System.Void"&&method.Parameters.Count==1&&method.Parameters[0].ParameterType.FullName=="System.Action`2<UnityEngine.Rendering.ScriptableRenderContext,UnityEngine.Camera>")));
        Check("native visibility calls target renderers while cockpit switch also changes audio",native.TryGetValue("Pilot",out var pilot)&&Calls(pilot.Methods.FirstOrDefault(method=>method.Name=="TogglePilotVisibility"),"UnityEngine.Renderer","set_enabled")&&native.TryGetValue("Aircraft",out var aircraft)&&Calls(aircraft.Methods.FirstOrDefault(method=>method.Name=="SetCockpitRenderers"),"IEngine","SetInteriorSounds"));
        Check("compiled bindings require playback exact actor player generation and ownership",AnyCall("ReplayMod.Core.ReplayRuntime","get_IsPlayback")&&AnyCall("ReplayMod.Core.Player","FindActor")&&AnyCall("ReplayMod.Core.Player","CurrentActorGeneration")&&AnyCall("ReplayMod.Core.ReplayManager","get_Playback")&&AnyCall("ReplayMod.Core.ReplayVfxPlayback","IsOwnedActor")&&AnyCall("ReplayMod.Core.Player","get_IsSeeking")&&AnyCall("ReplayMod.Misc.SceneHelper","get_IsTransitionPending")&&AnyField("GameManager","IsHeadless"));
        var bindingBody=Body(runtime,"ValidBinding");
        Check("compiled camera replacement validation binds manager main and overlay identities",bindingBody!=null&&new[]{"cameraManager","main","nativeOverlay"}.All(name=>bindingBody.Body.Instructions.Any(instruction=>instruction.Operand is FieldReference field&&field.DeclaringType.FullName==runtime&&field.Name==name))&&new[]{"mainCamera","cockpitCamRender"}.All(name=>bindingBody.Body.Instructions.Any(instruction=>instruction.Operand is FieldReference field&&field.DeclaringType.FullName=="CameraStateManager"&&field.Name==name)));
        Check("compiled eligibility excludes ejected dead inactive detached and fragmented seats",AnyCall("Aircraft","HasEjected")&&AnyCall("UnitPart","IsDetached")&&AnyCall("UnityEngine.GameObject","get_activeInHierarchy")&&AnyField("UnitPart","fragmented")&&AnyField("Pilot","dead")&&AnyField("Pilot","ejected"));
        const string seats="ReplayMod.Core.ReplayCockpitSeats";
        var eye=Body(seats,"TryEye");
        var seatBodies=compiled.Values.Where(type=>type.FullName==seats||type.FullName.StartsWith(seats+"/",StringComparison.Ordinal)).SelectMany(type=>type.Methods.Where(method=>method.HasBody)).ToArray();
        bool SeatField(string type,string name)=>seatBodies.Any(body=>body.Body.Instructions.Any(instruction=>instruction.Operand is FieldReference field&&field.DeclaringType.FullName==type&&field.Name==name));
        Check("eye resolver validates replay actor then delegates native seat pose",Calls(Body(runtime,"TryGetCockpitEye"),runtime,"ValidActor")&&Calls(Body(runtime,"TryGetCockpitEye"),seats,"TryEye")&&Calls(eye,"UnityEngine.Transform","get_position")&&Calls(eye,"UnityEngine.Transform","get_rotation")&&SeatField("Unit","cockpitViewPoint")&&SeatField("Aircraft","cockpit"));
        Check("native seat eye and crew bone APIs",Fields("Unit",("cockpitViewPoint","UnityEngine.Transform"))&&native.TryGetValue("UnityEngine.SkinnedMeshRenderer",out var skinned)&&skinned.Methods.Any(method=>method.Name=="get_bones"&&!method.IsStatic&&method.Parameters.Count==0&&method.ReturnType.FullName=="UnityEngine.Transform[]"));
        Check("additional seats use actual crew bones and reject dead ejected or detached occupants",Calls(Body(seats,"FindHead"),"UnityEngine.SkinnedMeshRenderer","get_bones")&&SeatField("Aircraft","pilots")&&SeatField("Pilot","dead")&&SeatField("Pilot","ejected")&&SeatField("Pilot","aircraft")&&Calls(eye,"UnitPart","IsDetached")&&Calls(eye,"UnityEngine.GameObject","get_activeInHierarchy")&&Calls(Body(runtime,"Clear"),seats,"Clear"));
        Check("compiled presentation uses existing renderers while retaining main projection",AnyField("Aircraft","cockpitRenderers")&&AnyField("Pilot","skinnedMeshRenderer")&&AnyCall("UnityEngine.Renderer","set_enabled")&&!AnyCall("UnityEngine.Camera","set_fieldOfView")&&AnyField("CameraStateManager","cockpitCamRender"));
        Check("external interiors use scoped main-camera layer rendering with native world depth",Calls(Body(runtime,"Apply"),"ReplayMod.Core.ReplayInteriorCameraMask","Apply")&&Calls(Body(runtime,"Apply"),"UnityEngine.Camera","set_cullingMask")&&Calls(Body(runtime,"Apply"),"UnityEngine.GameObject","get_layer")&&Calls(Body(runtime,"Clear"),"ReplayMod.Core.ReplayInteriorCameraMask","Restore"));
        Check("compiled controller and seat resolver leave actors pilot logic audio hierarchy and assets unchanged",bodies.Length>0&&seatBodies.Length>0&&bodies.Concat(seatBodies).All(body=>body.Body.Instructions.All(instruction=>
            (instruction.Operand is not MethodReference method||method.Name is not("Instantiate" or "Destroy" or "SetActive" or "SetParent" or "SetPositionAndRotation" or "SetCockpitRenderers" or "TogglePilotVisibility" or "SetInteriorSounds" or "SwitchState" or "SetEjected" or "SetFollowingUnit" or "SetLocalSim" or "SetAircraft" or "AttachToAircraft")&&!(method.DeclaringType.FullName=="UnityEngine.Transform"&&method.Name.StartsWith("set_",StringComparison.Ordinal)))&&
            (instruction.OpCode.Code is not(Mono.Cecil.Cil.Code.Stfld or Mono.Cecil.Cil.Code.Stsfld)||instruction.Operand is not FieldReference field||field.DeclaringType.FullName is not("Pilot" or "Aircraft" or "Unit" or "UnitPart" or "GameManager" or "Player")))));
        Check("compiled render pass subscription and clear remove ownership",WritesField(Body(runtime,"Update"),"UnityEngine.Camera","onPreCull")&&Calls(Body(runtime,"Update"),"System.Delegate","Combine")&&Calls(Body(runtime,"Update"),"UnityEngine.Rendering.RenderPipelineManager","add_beginCameraRendering")&&
            WritesField(Body(runtime,"Clear"),"UnityEngine.Camera","onPreCull")&&Calls(Body(runtime,"Clear"),"System.Delegate","Remove")&&Calls(Body(runtime,"Clear"),"UnityEngine.Rendering.RenderPipelineManager","remove_beginCameraRendering")&&
            Calls(Body(runtime,"BeforePipelineCameraRender"),runtime,"Apply")&&Calls(Body(runtime,"Clear"),"ReplayMod.Core.ReplayInteriorVisibilityState`1","Restore")&&Body(runtime,"Clear")?.Body.ExceptionHandlers.Any(handler=>handler.HandlerType==Mono.Cecil.Cil.ExceptionHandlerType.Finally)==true);
        Check("native mode baseline changes are observed by scoped postfixes",Calls(Body("ReplayMod.Patches.ReplayCockpitRendererVisibilityPatch","Postfix"),runtime,"NativeCockpitVisibilityChanged")&&Calls(Body("ReplayMod.Patches.ReplaySeatedPilotVisibilityPatch","Postfix"),runtime,"NativePilotVisibilityChanged")&&Calls(Body("ReplayMod.Patches.ReplayCockpitOverlayModePatch","Postfix"),runtime,"NativeCameraModeChanged"));
        Check("native first-person camera always suppresses seated pilot head obstruction",Calls(Body(runtime,"Update"),runtime,"NativeEyeView")&&Calls(Body(runtime,"NativeCameraModeChanged"),runtime,"NativeEyeView")&&AnyField("CameraStateManager","followingUnit"));
        Check("compiled release does not re-enable ejected or removed originals",Calls(Body(runtime,"RestoreEligible"),runtime,"Eligible")&&Calls(Body(runtime,"Clear"),"ReplayMod.Core.ReplayInteriorVisibilityState`1","Restore"));
        Check("complementary exterior suppression requires native role and verified stand-in geometry",AnyField("Aircraft","exteriorRenderers")&&
            Calls(Body(runtime,"VerifiedStandin"),"UnityEngine.Renderer","get_sharedMaterials")&&Calls(Body(runtime,"VerifiedStandin"),"UnityEngine.Bounds","Contains")&&
            Body(runtime,"VerifiedStandin")?.Body.Instructions.Any(instruction=>instruction.Operand is string name&&name=="Matte_black")==true&&
            Body(runtime,"Apply")?.Body.Instructions.Any(instruction=>instruction.Operand is FieldReference field&&field.Name=="verifiedStandin")==true&&
            Calls(Body(runtime,"Apply"),"ReplayMod.Core.ReplayInteriorVisibilityState`1","Release"));
        Check("other cockpits are isolated only for exact owned actors and newly exposed layers",Calls(Body(runtime,"ActorSpawned"),runtime,"ValidBinding")&&
            Calls(Body(runtime,"ActorSpawned"),"ReplayMod.Core.Player","OwnsReplayAircraft")&&Calls(Body(runtime,"ActorSpawned"),"ReplayMod.Core.ReplayInteriorCameraMask","get_AddedLayers")&&
            Calls(Body(runtime,"OtherEligible"),"ReplayMod.Core.Player","CurrentActorGeneration")&&Calls(Body(runtime,"OtherEligible"),"ReplayMod.Core.Player","FindActor")&&
            Calls(Body(runtime,"OtherEligible"),"UnitPart","IsDetached")&&Calls(Body(runtime,"Clear"),"ReplayMod.Core.ReplayInteriorVisibilityState`1","Restore"));
        const string screens="ReplayMod.Core.ReplayCockpitFlightScreens";
        var screenBodies=compiled.Values.Where(type=>type.FullName==screens||type.FullName.StartsWith(screens+"/",StringComparison.Ordinal)).SelectMany(type=>type.Methods.Where(method=>method.HasBody)).ToArray();
        Check("physical screen sampling uses recorded pose instead of kinematic rigidbody velocity",Calls(Body(screens,"Update"),"ReplayMod.Core.Player","TryGetRecordedPose")&&
            screenBodies.All(body=>!Calls(body,"UnityEngine.Rigidbody","get_velocity"))&&Calls(Body(screens,"Update"),"ReplayMod.Core.ReplayFlightInstrumentDisplay","Render")&&
            Calls(Body(screens,"Update"),"System.Math","Sqrt")&&!Calls(Body(screens,"Update"),"UnityEngine.Vector3","get_magnitude"));
        Check("physical screens use private pixels and exact native texture slot identification",Calls(Body(screens,"Update"),"UnityEngine.Texture2D","SetPixels32")&&
            Calls(Body(screens,"Bind"),"UnityEngine.Material","GetTexture")&&Body(screens,"Bind")?.Body.Instructions.Any(instruction=>instruction.Operand is string name&&name=="TacScreenRenderer")==true&&
            Calls(Body(screens,"Clear"),"UnityEngine.MaterialPropertyBlock","GetTexture")&&Calls(Body(screens,"Clear"),"UnityEngine.Object","Destroy"));
        Check("physical screens never mutate shared materials native HUDs or player ownership",screenBodies.Length>0&&screenBodies.All(body=>body.Body.Instructions.All(instruction=>
            instruction.Operand is not MethodReference method||method.DeclaringType.FullName is not("CombatHUD" or "FlightHud" or "TacScreen" or "TargetCam" or "MFDAppManager" or "GameManager" or "UnityEngine.Graphics")&&
            !(method.DeclaringType.FullName=="UnityEngine.Material"&&method.Name.StartsWith("Set",StringComparison.Ordinal))&&method.Name is not("SetAircraft" or "AttachToAircraft" or "SetLocalSim" or "SetFollowingUnit"))));
        Check("native remote cockpit animation restores enabled flag without initializing tactical UI",Fields("Cockpit",("aircraft","Aircraft"))&&AnyCall("UnityEngine.Behaviour","set_enabled")&&
            Calls(Body(runtime,"Clear"),"ReplayMod.Core.ReplayOwnedOverrideCache`2","Restore")&&bodies.All(body=>!Calls(body,"Cockpit","Cockpit_OnAircraftInitialize")&&!Calls(body,"TacScreen","Initialize")));
        Console.WriteLine($"Replay interior API/integration audit: {checks} groups, {failures} failures");
        return(checks,failures);
    }
    private static IEnumerable<TypeDefinition> AllTypes(IEnumerable<TypeDefinition> types)
    {foreach(var type in types){yield return type;foreach(var child in AllTypes(type.NestedTypes))yield return child;}}
}
